source:
struct Base { virtual ~Base(); int x; };
struct Mixin { virtual void tick(); char tag; };
struct Derived : Base, Mixin { char extra; };
struct Diamond : virtual Base { double d; };
class Secret { class Inner { char c[3]; }; Inner priv; public: int pub; };
struct Empty {};
struct WithEbo : Empty { char c; };
template <typename T> struct Pair { T first; char second; };
Pair<double> pd; Pair<char> pc;

